import {challenge as C} from './shared.js';
export default [
C(7,2,'实现一次扩散加噪',{
 goal:'按给定累计信号系数混合干净数据与噪声。',signature:'add_noise(clean, noise, alpha_bar)',contract:'clean、noise 等长，0≤alpha_bar≤1。返回 sqrt(alpha_bar)*clean + sqrt(1-alpha_bar)*noise 的逐项结果；noise 已给定，不再随机采样。',context:'前向加噪是构造训练输入的一步。噪声预测模型接收混合结果和时间条件，但本函数没有可训练参数。固定噪声能让手算与代码一致，也便于做受控对比。',steps:['计算信号系数 sqrt(alpha_bar)。','计算噪声系数 sqrt(1-alpha_bar)。','逐项相加，检查两个端点分别得到原数据与纯噪声。'],worked:['clean=[2]、noise=[0]、alpha_bar=0.25。','信号系数 0.5，噪声系数约 0.866。','结果为 [1]；不能直接用 0.25 乘信号。'],mistake:'这里传入的是累计 alpha_bar，不是每一步 alpha；不能把二者混用。',transfer:'训练目标还可能是噪声、干净样本或速度参数化；加噪公式本身并不能确定具体训练目标。',cases:[['add_noise([2],[0],0.25)','[1]','平方根系数'],['add_noise([1,2],[9,8],1)','[1,2]','无噪声端点'],['add_noise([1,2],[9,8],0)','[9,8]','纯噪声端点']],solution:'import math\ndef add_noise(clean,noise,alpha_bar):\n    return [math.sqrt(alpha_bar)*x+math.sqrt(1-alpha_bar)*n for x,n in zip(clean,noise)]\n',quiz:['alpha_bar=0 时结果是什么？',['干净数据','给定噪声','零向量'],1,'信号系数为零，噪声系数为一。']
}),
C(7,4,'构造 Flow Matching 的直线路径目标',{
 goal:'同时返回路径上的样本与其目标速度。',signature:'flow_pair(noise, data, t)',contract:'noise、data 为等长向量，0≤t≤1。约定 t=0 为噪声、t=1 为数据。返回 (x_t,velocity)，x_t=(1-t)*noise+t*data，velocity=data-noise。',context:'Flow Matching 学习的是沿指定概率路径的速度场。先明确时间方向，再推导路径导数，避免把噪声到数据与数据到噪声的符号混淆。本题给的是条件直线路径上的训练对，不是已经学会的整体速度场。',steps:['按 t 对两端点线性插值。','对 t 求导得到 data-noise，直线路径中它不依赖 t。','同时返回位置和速度，让下游损失能对照模型预测。'],worked:['noise=[0,2]，data=[4,0]，t=0.25。','位置 [1,1.5]。','速度始终 [4,-2]，方向指向数据端。'],mistake:'把当前 x_t 当作速度目标会改变训练问题。',transfer:'实际模型只看到条件输入并学习期望速度；本题知道两个端点，因此不能将这个数值构造宣称为生成模型。',cases:[['flow_pair([0,2],[4,0],0.25)','([1,1.5],[4,-2])','插值与导数'],['flow_pair([1],[3],0)','([1],[2])','噪声端'],['flow_pair([1],[3],1)','([3],[2])','数据端']],solution:'def flow_pair(noise,data,t):\n    return ([(1-t)*n+t*d for n,d in zip(noise,data)],[d-n for n,d in zip(noise,data)])\n',quiz:['本题时间从噪声指向数据，速度应为？',['noise-data','data-noise','data+noise'],1,'对 (1-t)*noise+t*data 求导。']
}),
C(7,6,'组合条件与无条件预测',{
 goal:'实现本题明确约定的 classifier-free guidance 组合。',signature:'guided_prediction(unconditional, conditional, scale)',contract:'两组等长向量，返回 u+scale*(c-u)。scale 可为任意有限数。这里仅做预测组合，不包含完整采样器。',context:'CFG 通过改变条件与无条件预测的组合，加强或减弱条件影响。不同论文和库可能使用不同的 scale 参数约定，所以只看变量名不够。本题固定公式，先用端点验证语义。',steps:['计算逐项差值 conditional-unconditional。','乘 scale 后加回 unconditional。','检查 scale=0、1；大于 1 是外推，不是概率平均。'],worked:['u=[1,2]，c=[3,0]。','scale=2 时结果 [5,-2]。','超出两个输入范围是这个公式允许的，不能擅自截断。'],mistake:'把 scale 当成 [0,1] 内的概率会错误限制 guidance 的定义。',transfer:'更强 guidance 不保证更好，多样性、伪影和条件一致性需要在固定采样预算下评估。',cases:[['guided_prediction([1,2],[3,0],2)','[5,-2]','条件外推'],['guided_prediction([1],[3],0)','[1]','无条件端点'],['guided_prediction([1],[3],1)','[3]','条件端点']],solution:'def guided_prediction(unconditional,conditional,scale):\n    return [u+scale*(c-u) for u,c in zip(unconditional,conditional)]\n',quiz:['按本题公式 scale=1 对应什么？',['无条件预测','条件预测','二者之和'],1,'u+(c-u)=c；遇到其他实现仍要核对其约定。']
}),
C(7,7,'周项目：写一个可替换速度场的采样器',{
 goal:'实现从 t=0 到 t=1 的显式 Euler 积分，并保留整个轨迹。',signature:'sample_flow(initial, steps, velocity)',contract:'initial 为向量，steps≥1，velocity(state,t) 返回同维速度。dt=1/steps，每步先用旧 state、t 计算速度，再同时更新全部坐标。返回包含初始状态的 steps+1 个状态列表。',context:'模型负责预测局部速度，采样器负责把多次局部预测积成轨迹。分开接口后，可以替换速度场或步数，观察误差从哪里来。测试中的已知速度场只是采样器验收，不代表训练好了图像模型。',steps:['复制初始状态并放入轨迹，避免后续原地修改历史。','第 k 步时间 t=k/steps，把当前状态交给 velocity。','用新列表计算 state+dt*v，保存，再进行下一步。'],worked:['初始 [0]，steps=2，速度恒为 [2]。','dt=0.5，第一步到 [1]，第二步到 [2]。','若速度依赖状态，必须每步重新调用，不能只在起点算一次。'],mistake:'重复把同一个可变列表 append 到轨迹会让所有历史状态看起来一样。',transfer:'真实 diffusion/flow 采样器还涉及具体时间参数化和数值方法；本题清楚隔开“速度预测”和“数值积分”。',cases:[['sample_flow([0],2,lambda s,t:[2])','[[0],[1],[2]]','恒定速度'],['sample_flow([1],2,lambda s,t:s)','[[1],[1.5],[2.25]]','依赖当前状态'],['sample_flow([0],2,lambda s,t:[t])','[[0],[0],[0.25]]','正确时间位置']],extraTests:[{name:'积分细化改善已知方程误差',code:'import math\na=sample_flow([1],4,lambda s,t:s)[-1][0]\nb=sample_flow([1],40,lambda s,t:s)[-1][0]\nassert abs(b-math.e)<abs(a-math.e)'}],solution:'def sample_flow(initial,steps,velocity):\n    state=list(initial); path=[list(state)]\n    for k in range(steps):\n        v=velocity(list(state),k/steps)\n        state=[x+d/steps for x,d in zip(state,v)]\n        path.append(list(state))\n    return path\n',quiz:['速度依赖当前状态时，为什么每步都要重新预测？',['因为新状态会改变速度','为了随机打乱目标','因为参数每步必定训练一次'],0,'采样步数不是训练更新次数。']
})];
